import { createOptionalContext } from "../../utils/optional-context.js";
/**
 * Default motion configuration
 */
export const defaultConfig = {
    reducedMotion: "never",
    transition: undefined,
    nonce: undefined,
};
export const [getMotionConfig, setMotionConfig] = createOptionalContext();
/** A getter for the closest MotionConfig's configuration, or the default one. */
export function useMotionConfig() {
    return getMotionConfig() ?? (() => defaultConfig);
}
